import math
from numbers import Real


def _values(source, name):
    if isinstance(source, (str, bytes)):
        raise ValueError(f"{name} must be a numeric iterable")
    try:
        raw = list(source)
    except TypeError as exc:
        raise ValueError(f"{name} must be iterable") from exc
    values = []
    for value in raw:
        if isinstance(value, bool) or not isinstance(value, Real):
            raise ValueError(f"{name} contains a non-number")
        number = float(value)
        if not math.isfinite(number):
            raise ValueError(f"{name} contains a non-finite number")
        values.append(number)
    return values


class LinearFit:
    def __init__(self, slope, intercept):
        self._slope = float(slope)
        self._intercept = float(intercept)

    @property
    def slope(self):
        return self._slope

    @property
    def intercept(self):
        return self._intercept

    @classmethod
    def fit(cls, xs, ys):
        x_values = _values(xs, "xs")
        y_values = _values(ys, "ys")
        if len(x_values) != len(y_values) or len(x_values) < 2:
            raise ValueError("fit requires equal lengths of at least two")
        mean_x = sum(x_values) / len(x_values)
        mean_y = sum(y_values) / len(y_values)
        denominator = sum((x - mean_x) ** 2 for x in x_values)
        if denominator == 0:
            raise ValueError("x values must not all be equal")
        numerator = sum((x - mean_x) * (y - mean_y) for x, y in zip(x_values, y_values))
        slope = numerator / denominator
        return cls(slope, mean_y + slope * mean_x)

    def predict(self, x):
        values = _values([x], "x")
        return self._slope * values[0] + self._intercept

    def predict_many(self, xs):
        return [self._slope * x + self._intercept for x in _values(xs, "xs")]

    def coefficients(self):
        return (self._slope, self._intercept)

    def residuals(self, xs, ys):
        x_values = _values(xs, "xs")
        y_values = _values(ys, "ys")
        if len(x_values) != len(y_values) or not x_values:
            raise ValueError("residuals require equal non-empty inputs")
        return [y - (self._slope * x + self._intercept) for x, y in zip(x_values, y_values)]

